import json,numpy as np
from PIL import Image
for folder in ['1791024951_lower_to_grasp_after','1791025071_close_on_cube_after','1791025082_check_lift_after']:
 m=json.load(open('/app/output/'+folder+'/meta.json'));K=np.array(m['cameras']['right']['intrinsic_cv']);T=np.array(m['cameras']['right']['cam2world_gl']);d=np.load('/app/output/'+folder+'/right_depth.npy')[0].astype(float);im=np.array(Image.open('/app/output/'+folder+'/right.png'));print('\n',folder)
 for v in range(118,132,2):
  for u in range(147,163,3):
   if im[v,u,0]>60 and im[v,u,1]<50 and im[v,u,2]<50:
    z=d[v,u];p=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);w=T@p;print((u,v),im[v,u].tolist(),round(z,2),np.round(w[:3],3))
