for v in range(108,125,2):
 for u in range(137,164,2):
  pix=im[v,u];
  # show strong red/white/cyan only
  if (pix[0]>100 and pix[1]<80 and pix[2]<80) or (pix[0]>140 and pix[1]>140 and pix[2]>140) or (pix[1]>100 and pix[1]>1.5*pix[0]):
   z=d[v,u];p=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);w=T@p;print((u,v),pix.tolist(),round(z,2),np.round(w[:3],3))
